using System;using System.IO;using System.Security.Cryptography;using System.Text;using System.Threading;using System.Threading.Tasks;using Newtonsoft.Json.Linq;using UnityEditor;
namespace SpatialWallpaper.Sdk.Editor {
 [InitializeOnLoad]public static class SandboxPreviewController {
  const string RecoveryKey="SpatialWallpaper.SandboxPreview.Owner.v1",ErrorKey="SpatialWallpaper.SandboxPreview.Error.v1",SnapshotKey="SpatialWallpaper.SandboxPreview.Snapshot.v1";static readonly int ownerThread=Thread.CurrentThread.ManagedThreadId;static SandboxPreviewSnapshot snapshot;static SandboxPreviewRun active;static string error;static bool recoveryBlocked,persistedPresented;static Task recovery=Task.CompletedTask;
  static CancellationTokenSource restarting;static Task restart=Task.CompletedTask;
  public static string State=>recoveryBlocked?"RecoveryBlocked":restarting!=null?"Restarting":active?.State??"Stopped";public static string Error=>active?.Error??error;public static bool ResourcesReleased=>!recoveryBlocked&&restarting==null&&(active==null||active.ResourcesReleased);public static bool RecoveryPending=>recoveryBlocked;public static JObject LastReceipt=>active?.LastReceipt;
  public static string BuildId=>snapshot?.BuildId;public static string[] Capabilities=>snapshot==null?new string[0]:(string[])snapshot.Capabilities.Clone();public static bool CanExport=>!recoveryBlocked&&snapshot?.Presented==true;
  static SandboxPreviewController(){EditorApplication.update+=Tick;AssemblyReloadEvents.beforeAssemblyReload+=BeforeReload;EditorApplication.quitting+=BeforeQuit;string saved=SessionState.GetString(RecoveryKey,"");error=SessionState.GetString(ErrorKey,"");if(error=="")error=null;
   if(saved!=""){recoveryBlocked=true;try{var record=JObject.Parse(saved);snapshot=SandboxPreviewSnapshot.Restore(record);active=SandboxPreviewRun.Restore(snapshot,record,Save);Observe(RetryRecoveryAsync());}catch(Exception fault){error="preview-recovery-unproven:"+fault.GetBaseException().Message;SessionState.SetString(ErrorKey,error);}}
   else{string prepared=SessionState.GetString(SnapshotKey,"");if(prepared!="")try{snapshot=SandboxPreviewSnapshot.Restore(JObject.Parse(prepared));persistedPresented=snapshot.Presented;}catch(Exception fault){error="preview-snapshot-recovery:"+fault.GetBaseException().Message;}}
  }
  static void RequireOwner(){if(Thread.CurrentThread.ManagedThreadId!=ownerThread)throw new InvalidOperationException("preview-editor-owner-thread");}
  static void Save(JObject record){if(record==null)SessionState.EraseString(RecoveryKey);else SessionState.SetString(RecoveryKey,record.ToString(Newtonsoft.Json.Formatting.None));}
  static async void Observe(Task operation){try{await operation;}catch(OperationCanceledException){}catch(Exception fault){error=fault.GetBaseException().Message;}}
  static void SaveSnapshot(){if(snapshot!=null){SessionState.SetString(SnapshotKey,snapshot.Record().ToString(Newtonsoft.Json.Formatting.None));persistedPresented=snapshot.Presented;}}
  static void Tick(){active?.Poll();if(snapshot!=null&&snapshot.Presented!=persistedPresented)SaveSnapshot();}
  static void BeforeReload(){try{restarting?.Cancel();active?.StopForReload();}catch(Exception fault){SessionState.SetString(ErrorKey,"preview-reload-cleanup-unproven:"+fault.GetBaseException().Message);}finally{snapshot?.Dispose();}}
  static void BeforeQuit(){BeforeReload();if(!recoveryBlocked&&(active==null||active.NativeResourcesReleased))try{snapshot?.Retire();SessionState.EraseString(SnapshotKey);}catch(Exception fault){SessionState.SetString(ErrorKey,"preview-cache-cleanup:"+fault.GetBaseException().Message);}}
  public static string DefaultDataDirectory(){string project=Path.GetFullPath(".");string key;using(var sha=SHA256.Create())key=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(project))).Replace("-","").Substring(0,12).ToLowerInvariant();return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SpatialWallpaper","SdkPreview",key);}
  public static void Prepare(SceneDefinition definition,string dataDirectory){RequireOwner();if(!ResourcesReleased)throw new InvalidOperationException("preview-editor-runtime-still-owned");active?.Dispose();active=null;var prepared=SandboxPreviewSnapshot.Create(definition,dataDirectory);var previous=snapshot;snapshot=prepared;SaveSnapshot();error=null;SessionState.EraseString(ErrorKey);previous?.Retire();}
  public static Task StartAsync(string runtimeDirectory,string attemptsDirectory,int width,int height,float physicalWidth,float physicalHeight){RequireOwner();if(!ResourcesReleased)throw new InvalidOperationException("preview-editor-runtime-still-owned");return StartPrepared(runtimeDirectory,attemptsDirectory,width,height,physicalWidth,physicalHeight);}
  static Task StartPrepared(string runtimeDirectory,string attemptsDirectory,int width,int height,float physicalWidth,float physicalHeight){if(snapshot==null)throw new InvalidOperationException("preview-snapshot-required");if(recoveryBlocked||active!=null&&!active.ResourcesReleased)throw new InvalidOperationException("preview-editor-runtime-still-owned");active?.Dispose();active=new SandboxPreviewRun(snapshot,Save);error=null;return active.StartAsync(runtimeDirectory,attemptsDirectory,width,height,physicalWidth,physicalHeight);}
  public static Task RestartAsync(string runtimeDirectory,string attemptsDirectory,int width,int height,float physicalWidth,float physicalHeight){RequireOwner();if(snapshot==null)throw new InvalidOperationException("preview-snapshot-required");if(recoveryBlocked||restarting!=null)throw new InvalidOperationException("preview-editor-restart-already-owned");var cancel=new CancellationTokenSource();restarting=cancel;restart=RestartCore(runtimeDirectory,attemptsDirectory,width,height,physicalWidth,physicalHeight,cancel);return restart;}
  static async Task RestartCore(string runtimeDirectory,string attemptsDirectory,int width,int height,float physicalWidth,float physicalHeight,CancellationTokenSource cancel){try{await(active?.StopAsync()??Task.CompletedTask);cancel.Token.ThrowIfCancellationRequested();await StartPrepared(runtimeDirectory,attemptsDirectory,width,height,physicalWidth,physicalHeight);}catch(Exception fault){if(!(fault is OperationCanceledException))error=fault.GetBaseException().Message;throw;}finally{restarting=null;cancel.Dispose();}}
  public static Task StopAsync(){RequireOwner();var pending=restarting!=null?restart:Task.CompletedTask;restarting?.Cancel();return StopAndJoin(active?.StopAsync()??Task.CompletedTask,pending);}
  static async Task StopAndJoin(Task stopping,Task pendingRestart){await stopping;try{await pendingRestart;}catch(OperationCanceledException){}}
  public static Task RetryRecoveryAsync(){RequireOwner();if(!recovery.IsCompleted)return recovery;var completion=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);recovery=completion.Task;Recover(completion);return recovery;}
  static async void Recover(TaskCompletionSource<bool> completion){try{if(active!=null){await active.StopAsync();if(!active.ResourcesReleased)throw new InvalidOperationException("preview-recovery-runtime-still-owned");}else{string saved=SessionState.GetString(RecoveryKey,"");if(saved=="")throw new InvalidOperationException("preview-recovery-record-missing");await SandboxPreviewRecovery.ReleaseAsync(JObject.Parse(saved));}Save(null);recoveryBlocked=false;error=null;SessionState.EraseString(ErrorKey);completion.TrySetResult(true);}catch(Exception fault){recoveryBlocked=true;error="preview-recovery-unproven:"+fault.GetBaseException().Message;SessionState.SetString(ErrorKey,error);completion.TrySetException(fault);}}
  public static void Export(string path){RequireOwner();if(snapshot==null)throw new InvalidOperationException("preview-snapshot-required");snapshot.Export(path);}
 }
}
